-- V26 — Gate-pass field: scan / pick / type, showing only AVAILABLE passes.
-- Every dispatch/QC screen's Gate Pass # field is now a searchable picker
-- (SearchableMultiColumnDropdown) sourced from the GatePass 'gpNumbers' lookup
-- (which already excludes CLOSED/REJECTED and — as of this change — 'probe-%'
-- schema-init rows), with freeSolo (hand-key a number) + scannable (QR/barcode)
-- turned on. Six screens that were still a raw text box become the picker.
-- Bodies are served live from page_version, so this migration only backfills
-- fresh DBs; the widget flags (freeSolo/scannable) are read by registry.js.
-- Idempotent: re-applies only where the body has not yet been converted.
UPDATE page_version pv JOIN page_definition pd ON pd.current_version_id=pv.id
SET pv.body_json='{"kind": "layout", "schemaVersion": 2, "slug": "aria:parking-scan", "title": "Parking-Bay Scan", "status": "published", "version": 1, "roles": ["ParkingSecurity", "Dispatch", "Manager", "TenantAdmin"], "dataSources": [], "streams": [], "entity": "ParkingBayEntry", "layout": [{"kind": "Grid", "columns": 12, "gap": 16, "children": [{"kind": "Section", "title": "Scan / Select Gate-Pass", "span": 12, "subtitle": "Tap Scan to use the camera, or pick the Gate Pass # from the list — vehicle, flow and loading context fill in automatically.", "children": [{"kind": "QrScan", "label": "Tap to Scan", "targetField": "gpNumber", "manualFallback": true}, {"kind": "Form", "submitLabel": "", "bindings": {"fields": [{"name": "gpNumber", "label": "Gate Pass #", "type": "select", "required": true, "placeholder": "Scan above or select Gate Pass #", "optionsSource": {"type": "entity", "entity": "GatePass", "lookupType": "gpNumbers", "valueField": "gp_number", "labelField": "gp_number"}, "onChangeFill": {"vehicleNo": "vehicle_no", "flowVariantCode": "flow_variant_code", "loadingType": "loading_type", "instanceId": "workflow_instance_id"}, "scannable": true, "freeSolo": true}, {"name": "vehicleNo", "label": "Vehicle Number", "type": "text", "disabled": true}, {"name": "flowVariantCode", "label": "Flow Variant", "type": "text", "disabled": true}, {"name": "loadingType", "label": "Loading Type", "type": "text", "disabled": true}, {"name": "instanceId", "label": "Workflow Instance", "type": "text", "disabled": true}]}}]}, {"kind": "Section", "span": 12, "children": [{"kind": "WorkflowActionButton", "action": "workflow.transition", "label": "Confirm", "instanceId": "{{form.instanceId}}", "variant": "primary"}]}]}]}'
WHERE pd.code='aria:parking-scan' AND pv.body_json NOT LIKE '%"scannable"%';
