o", "type": "file", "accept": "image/*"}, {"name": "seal_unlock_no", "label": "Seal Unlock #", "type": "text"}, {"name": "qc_notes", "label": "Notes", "type": "textarea", "rows": 3}]}}]}, {"kind": "Section", "title": "Decision", "span": 12, "children": [{"kind": "Form", "bindings": {"fields": [{"name": "status", "label": "QC Decision", "type": "select", "required": true, "options": [{"label": "✓ APPROVED — all parameters pass", "value": "APPROVED"}, {"label": "✓ APPROVED with notes (managed exception)", "value": "APPROVED_NOTES"}, {"label": "✗ REJECTED — see notes / debit vendor", "value": "REJECTED"}]}]}}, {"kind": "WorkflowActionButton", "action": "workflow.transition", "label": "Submit QC Decision", "variant": "primary"}]}]}]}'
